let observer = null;

export function initScrollObserver(sentinelEl, scrollContainerEl, dotNetRef) {
    dispose();

    if (!sentinelEl || !scrollContainerEl) return;

    observer = new IntersectionObserver(
        (entries) => {
            if (entries[0].isIntersecting) {
                dotNetRef.invokeMethodAsync('OnScrolledToTop');
            }
        },
        { root: scrollContainerEl, threshold: 0.1 }
    );

    observer.observe(sentinelEl);
}

export function scrollToBottom(element) {
    if (element) {
        element.scrollTop = element.scrollHeight;
    }
}

export function getScrollHeight(element) {
    return element ? element.scrollHeight : 0;
}

export function preserveScroll(element, previousScrollHeight) {
    if (element) {
        element.scrollTop = element.scrollHeight - previousScrollHeight;
    }
}

export function dispose() {
    if (observer) {
        observer.disconnect();
        observer = null;
    }
}

.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

.sidebar-column {
    width: 20%;
    min-width: 200px;
    max-width: 300px;
    flex-shrink: 0;
}

.main-column {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-width: 0;
    background: #fff;
}

.thread-column {
    width: 25%;
    min-width: 280px;
    max-width: 420px;
    flex-shrink: 0;
}

.channel-header {
    padding: 12px 20px;
    border-bottom: 1px solid #e0e0e0;
    background: #fff;
    flex-shrink: 0;
}

.channel-header h2 {
    margin: 0;
    font-size: 18px;
    font-weight: 700;
}

.channel-header p {
    margin: 4px 0 0;
    font-size: 13px;
    color: #666;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

.scroll-sentinel {
    height: 1px;
}

.loading-indicator {
    text-align: center;
    padding: 12px;
    color: #999;
    font-size: 13px;
}

.no-channel-selected {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #999;
    font-size: 16px;
}

@page "/chat"
@rendermode InteractiveServer
@layout ChatLayout
@using sv_685905a285c34216978dfc93b9523cb9.Components.Chat
@using sv_685905a285c34216978dfc93b9523cb9.Components.Layout
@using sv_685905a285c34216978dfc93b9523cb9.Services
@inject IChatService ChatService
@inject IJSRuntime JS
@implements IAsyncDisposable

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="sidebar-column">
        <ChannelSidebar Channels="channels"
                        SelectedChannelId="selectedChannelId"
                        OnChannelSelected="SelectChannelAsync" />
    </div>

    <div class="main-column">
        @if (selectedChannel is not null)
        {
            <div class="channel-header">
                <h2># @selectedChannel.Name</h2>
                <p>@selectedChannel.Description</p>
            </div>

            <div class="message-list" @ref="messageListRef">
                <div @ref="scrollSentinelRef" class="scroll-sentinel"></div>

                @if (isLoadingMore)
                {
                    <div class="loading-indicator">Loading older messages…</div>
                }

                @foreach (var message in messages)
                {
                    <MessageItem Message="message"
                                 ThreadSummary="threadSummaries.GetValueOrDefault(message.Id)"
                                 OnReply="OpenThreadAsync"
                                 OnReact="HandleReactionAsync"
                                 OnViewThread="OpenThreadAsync" />
                }
            </div>

            <MessageInput Placeholder="@($"Message #{selectedChannel.Name}")"
                          OnSubmit="SendMessageAsync" />
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (threadRootMessage is not null)
    {
        <div class="thread-column">
            <ThreadPanel RootMessage="threadRootMessage"
                         Replies="threadMessages"
                         OnClose="CloseThread"
                         OnSendReply="SendThreadReplyAsync" />
        </div>
    }
</div>

@code {
    private const int PageSize = 50;

    private List<Channel> channels = [];
    private int? selectedChannelId;
    private Channel? selectedChannel;
    private List<Message> messages = [];
    private Dictionary<int, ThreadSummary> threadSummaries = [];
    private bool isLoadingMore;
    private bool hasMoreMessages = true;

    private Message? threadRootMessage;
    private List<Message> threadMessages = [];

    private ElementReference messageListRef;
    private ElementReference scrollSentinelRef;
    private IJSObjectReference? jsModule;
    private DotNetObjectReference<ChatPage>? dotNetRef;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannelAsync(channels[0].Id);
        }
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            jsModule = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./Components/Pages/ChatPage.razor.js");
            dotNetRef = DotNetObjectReference.Create(this);
            await SetupScrollObserverAsync();
        }
    }

    private async Task SetupScrollObserverAsync()
    {
        if (jsModule is null || dotNetRef is null) return;
        await jsModule.InvokeVoidAsync(
            "initScrollObserver", scrollSentinelRef, messageListRef, dotNetRef);
    }

    [JSInvokable]
    public async Task OnScrolledToTop()
    {
        if (isLoadingMore || !hasMoreMessages || selectedChannelId is null) return;

        isLoadingMore = true;
        StateHasChanged();

        var previousHeight = jsModule is not null
            ? await jsModule.InvokeAsync<double>("getScrollHeight", messageListRef)
            : 0;

        var olderMessages = await ChatService.GetMessagesAsync(
            selectedChannelId.Value, messages.Count, PageSize);

        if (olderMessages.Count < PageSize)
            hasMoreMessages = false;

        messages.InsertRange(0, olderMessages);
        RebuildThreadSummaries();

        isLoadingMore = false;
        StateHasChanged();

        if (jsModule is not null)
        {
            await Task.Yield();
            await jsModule.InvokeVoidAsync("preserveScroll", messageListRef, previousHeight);
        }
    }

    private async Task SelectChannelAsync(int channelId)
    {
        selectedChannelId = channelId;
        selectedChannel = channels.Find(c => c.Id == channelId);
        messages = [];
        hasMoreMessages = true;
        threadRootMessage = null;
        threadMessages = [];
        threadSummaries = [];

        var loaded = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        messages = loaded;
        if (loaded.Count < PageSize)
            hasMoreMessages = false;

        RebuildThreadSummaries();
        await ChatService.MarkChannelReadAsync(channelId);

        StateHasChanged();
        await Task.Yield();

        if (jsModule is not null)
        {
            await jsModule.InvokeVoidAsync("scrollToBottom", messageListRef);
            await SetupScrollObserverAsync();
        }
    }

    private async Task SendMessageAsync(string content)
    {
        if (selectedChannelId is null) return;

        var message = await ChatService.SendMessageAsync(selectedChannelId.Value, content, null);
        messages.Add(message);
        StateHasChanged();

        await Task.Yield();
        if (jsModule is not null)
        {
            await jsModule.InvokeVoidAsync("scrollToBottom", messageListRef);
        }
    }

    private async Task OpenThreadAsync(int messageId)
    {
        threadRootMessage = messages.Find(m => m.Id == messageId);
        if (threadRootMessage is null) return;

        threadMessages = await ChatService.GetThreadAsync(messageId);
    }

    private void CloseThread()
    {
        threadRootMessage = null;
        threadMessages = [];
    }

    private async Task SendThreadReplyAsync(string content)
    {
        if (threadRootMessage is null || selectedChannelId is null) return;

        var reply = await ChatService.SendMessageAsync(
            selectedChannelId.Value, content, threadRootMessage.Id);
        threadMessages.Add(reply);

        threadSummaries[threadRootMessage.Id] = new ThreadSummary(
            threadRootMessage.Id, threadMessages.Count, reply.SentAt);
    }

    private async Task HandleReactionAsync((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        var message = messages.Find(m => m.Id == args.MessageId);
        if (message is null) return;

        var existing = message.Reactions.Find(r => r.Emoji == args.Emoji);
        if (existing is not null)
        {
            existing.Users.Add("You");
        }
        else
        {
            message.Reactions.Add(new Reaction(args.Emoji, ["You"]));
        }
    }

    private void RebuildThreadSummaries()
    {
        threadSummaries = messages
            .Where(m => m.ReplyToId is not null)
            .GroupBy(m => m.ReplyToId!.Value)
            .ToDictionary(
                g => g.Key,
                g => new ThreadSummary(g.Key, g.Count(), g.Max(m => m.SentAt)));
    }

    public async ValueTask DisposeAsync()
    {
        if (jsModule is not null)
        {
            try
            {
                await jsModule.InvokeVoidAsync("dispose");
                await jsModule.DisposeAsync();
            }
            catch (JSDisconnectedException)
            {
                // Circuit already disconnected — safe to ignore
            }
        }
        dotNetRef?.Dispose();
    }
}

