        threadRootMessage = null;
        threadMessages = [];
    }

    private async Task SendThreadReplyAsync(string content)
    {
        if (threadRootMessage is null || selectedChannelId is null) return;

        var reply = await ChatService.SendMessageAsync(
            selectedChannelId.Value, content, threadRootMessage.Id);
        threadMessages.Add(reply);

        threadSummaries[threadRootMessage.Id] = new ThreadSummary(
            threadRootMessage.Id, threadMessages.Count, reply.SentAt);
    }

    private async Task HandleReactionAsync((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        var message = messages.Find(m => m.Id == args.MessageId);
        if (message is null) return;

        var existing = message.Reactions.Find(r => r.Emoji == args.Emoji);
        if (existing is not null)
        {
            existing.Users.Add("You");
        }
        else
        {
            message.Reactions.Add(new Reaction(args.Emoji, ["You"]));
        }
    }

    private void RebuildThreadSummaries()
    {
        threadSummaries = messages
            .Where(m => m.ReplyToId is not null)
            .GroupBy(m => m.ReplyToId!.Value)
            .ToDictionary(
                g => g.Key,
                g => new ThreadSummary(g.Key, g.Count(), g.Max(m => m.SentAt)));
    }

    public async ValueTask DisposeAsync()
    {
        if (jsModule is not null)
        {
            try
            {
                await jsModule.InvokeVoidAsync("dispose");
                await jsModule.DisposeAsync();
            }
            catch (JSDisconnectedException)
            {
                // Circuit already disconnected — safe to ignore
            }
        }
        dotNetRef?.Dispose();
    }
}

