        StateHasChanged();

        var previousHeight = jsModule is not null
            ? await jsModule.InvokeAsync<double>("getScrollHeight", messageListRef)
            : 0;

        var olderMessages = await ChatService.GetMessagesAsync(
            selectedChannelId.Value, messages.Count, PageSize);

        if (olderMessages.Count < PageSize)
            hasMoreMessages = false;

        messages.InsertRange(0, olderMessages);
        RebuildThreadSummaries();

        isLoadingMore = false;
        StateHasChanged();

        if (jsModule is not null)
        {
            await Task.Yield();
            await jsModule.InvokeVoidAsync("preserveScroll", messageListRef, previousHeight);
        }
    }

    private async Task SelectChannelAsync(int channelId)
    {
        selectedChannelId = channelId;
        selectedChannel = channels.Find(c => c.Id == channelId);
        messages = [];
        hasMoreMessages = true;
        threadRootMessage = null;
        threadMessages = [];
        threadSummaries = [];

        var loaded = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        messages = loaded;
        if (loaded.Count < PageSize)
            hasMoreMessages = false;

        RebuildThreadSummaries();
        await ChatService.MarkChannelReadAsync(channelId);

        StateHasChanged();
        await Task.Yield();

        if (jsModule is not null)
        {
            await jsModule.InvokeVoidAsync("scrollToBottom", messageListRef);
            await SetupScrollObserverAsync();
        }
    }

